        token.blacklistAddress(user);

        // Verify blacklist status changed
        assertTrue(token.isAddressBlacklisted(user), "User should be blacklisted after owner action");

        // Attempt transfer from blacklisted address
        vm.prank(user);
        vm.expectRevert(); 
        token.transfer(address(0x123), 100 ether);
    }

    function test_nonowner_cannot_blacklist() public {
        // Non-owner attempts to blacklist
        vm.prank(user);
        vm.expectRevert("Ownable: caller is not the owner");
        token.blacklistAddress(user);
    }

    function test_renouncing_ownership_removes_blacklist_power() public {
        // Owner renounces ownership
        vm.prank(owner);
        token.renounceOwnership();

        // Verify ownership transferred to zero address
        assertEq(token.owner(), address(0), "Ownership not renounced");

        // Attempt to blacklist after ownership renounced
        vm.prank(owner);
        vm.expectRevert("Ownable: caller is not the owner");
        token.blacklistAddress(user);
    }
}
